    proxmox = {
      source  = "bpg/proxmox"
      version = "~> 0.69"
    }
    time = {
      source  = "hashicorp/time"
      version = "~> 0.12"
    }
    null = {
      source  = "hashicorp/null"
      version = "~> 3.2"
    }
  }
}

