terraform {
  required_providers {
    proxmox = {
      source  = "bpg/proxmox"
      version = "~> 0.69"
    }
    time = {
      source  = "hashicorp/time"
      version = "~> 0.12"
    }
    ansible = {
      source  = "marshallford/ansible"
      version = "~> 0.9"
    }
  }
}

resource "proxmox_virtual_environment_container" "lxc" {
  node_name   = var.proxmox_node
  vm_id       = var.container_id
  description = var.description
  tags        = var.tags

  # Template
  operating_system {
    template_file_id = var.template
    type             = var.os_type
  }

  # Compute
  cpu {
    cores = var.cores
  }

  memory {
    dedicated = var.memory
    swap      = var.swap
  }

  # Root filesystem
  disk {
    datastore_id = var.rootfs_storage
    size         = var.rootfs_size
  }

  # Additional mount points
  dynamic "mount_point" {
    for_each = var.mount_points
    content {
      volume = mount_point.value.volume
      path   = mount_point.value.path
      backup = mount_point.value.backup
      quota  = mount_point.value.quota
    }
  }

  # Primary network - Container network (vmbr1, 10.100.x.x)
  network_interface {
    name   = "eth0"
    bridge = "vmbr1"
  }

  # Secondary network - LAN (vmbr0, 192.168.1.x) - only if lan_ip is set
  dynamic "network_interface" {
    for_each = var.lan_ip != "" ? [1] : []
    content {
      name   = "eth1"
      bridge = "vmbr0"
    }
  }

  initialization {
    hostname = var.name

    # eth0 - Container network (required)
    ip_config {
      ipv4 {
        address = var.container_ip
        gateway = var.container_gateway
      }
    }

    # eth1 - LAN network (optional)
    dynamic "ip_config" {
      for_each = var.lan_ip != "" ? [1] : []
      content {
        ipv4 {
          address = var.lan_ip
          gateway = null  # Don't set gateway on secondary interface
        }
      }
    }

    user_account {
      keys = [var.ssh_public_key]
    }
  }

  # GPU Device Passthrough and custom devices are configured via SSH
  # The API token doesn't have permission for device_passthrough (requires root@pam)
  # See null_resource.configure_gpu_passthrough below

  # Container features
  # Note: API tokens can only set features on unprivileged containers
  # For privileged containers, all features are configured via SSH in configure_container_features
  dynamic "features" {
    for_each = var.unprivileged ? [1] : []
    content {
      nesting = var.enable_nesting
    }
  }

  unprivileged = var.unprivileged

  # Lifecycle
  started       = var.start_on_create
  start_on_boot = var.start_on_boot

  # Lifecycle - ignore create-time-only attributes that would force replacement
  # These attributes cannot be changed on existing containers and must be ignored
  # for imported containers to work properly
  lifecycle {
    ignore_changes = [
      # These are create-time-only and would force replacement if changed
      operating_system,   # template_file_id
      initialization,     # user_account.keys, hostname
      unprivileged,       # cannot change privileged/unprivileged after creation
      disk,               # cannot change storage or reduce size after creation
      features,           # API token can't modify features on privileged containers (requires root@pam)
      tags,               # tags are additionally modified via cron jobs outside of Terraform
      device_passthrough, # GPU devices may be added manually via SSH (API token can't manage these)
      console,            # console settings may be modified outside of Terraform
      start_on_boot,      # may be set outside of Terraform
      mount_point,        # mount points configured outside Terraform (API token limitations)
      # Timeout values are not actual container properties, ignore them on imported resources
      timeout_clone,
      timeout_create,
      timeout_delete,
      timeout_start,
      timeout_update,
    ]
  }
}

# Configure LXC container via Ansible (replaces null_resource provisioners)
# Configures features, GPU passthrough, and mount points on Proxmox host
resource "ansible_navigator_run" "configure_lxc" {
  count = (var.enable_keyctl || var.enable_fuse || !var.unprivileged || var.enable_gpu || length(var.mount_points) > 0) && var.proxmox_ssh_host != "" ? 1 : 0

  depends_on = [proxmox_virtual_environment_container.lxc]

  triggers = {
    container_id   = var.container_id
    unprivileged   = var.unprivileged
    enable_nesting = var.enable_nesting
    enable_keyctl  = var.enable_keyctl
    enable_fuse    = var.enable_fuse
    enable_gpu     = var.enable_gpu
    mount_points   = jsonencode(var.mount_points)
  }

  execution_environment = {
    enabled = false  # Run ansible directly on host, not in container
  }

  ansible_options = {
    private_keys = [{
      name = "homelab"
      data = file(var.proxmox_ssh_private_key_path)
    }]
  }

  playbook = <<-EOT
    - name: Configure LXC ${var.container_id}
      hosts: proxmox
      gather_facts: no
      vars:
        container_id: ${var.container_id}
        unprivileged: ${var.unprivileged}
        enable_nesting: ${var.enable_nesting}
        enable_keyctl: ${var.enable_keyctl}
        enable_fuse: ${var.enable_fuse}
        enable_gpu: ${var.enable_gpu}
        mount_points: ${jsonencode(var.mount_points)}
        lxc_conf_path: "/etc/pve/lxc/${var.container_id}.conf"

      tasks:
        # =====================================================================
        # Container Features (nesting, keyctl, fuse)
        # =====================================================================
        - name: Configure AppArmor for privileged container
          ansible.builtin.lineinfile:
            path: "{{ lxc_conf_path }}"
            line: "lxc.apparmor.profile: unconfined"
            state: present
          when: not unprivileged

        - name: Set container features
          ansible.builtin.command:
            cmd: >
              pct set {{ container_id }}
              --features nesting={{ enable_nesting | int }},keyctl={{ enable_keyctl | int }},fuse={{ enable_fuse | int }}
          changed_when: true

        # =====================================================================
        # GPU Passthrough (AMD)
        # =====================================================================
        - name: Stop container for GPU config
          ansible.builtin.command:
            cmd: pct stop {{ container_id }}
          when: enable_gpu
          register: gpu_stop
          failed_when: gpu_stop.rc != 0 and 'not running' not in gpu_stop.stderr

        - name: Add GPU device passthrough
          ansible.builtin.blockinfile:
            path: "{{ lxc_conf_path }}"
            marker: "# {mark} GPU PASSTHROUGH - MANAGED BY OPENTOFU"
            block: |
              dev0: /dev/dri/card0,gid=44
              dev1: /dev/dri/renderD128,gid=104
              dev2: /dev/kfd
              lxc.cgroup2.devices.allow: c 226:* rwm
              lxc.cgroup2.devices.allow: c 234:* rwm
          when: enable_gpu

        # =====================================================================
        # Mount Points
        # =====================================================================
        - name: Stop container for mount config
          ansible.builtin.command:
            cmd: pct stop {{ container_id }}
          when: mount_points | length > 0
          register: mount_stop
          failed_when: mount_stop.rc != 0 and 'not running' not in mount_stop.stderr

        - name: Configure mount points
          ansible.builtin.command:
            cmd: "pct set {{ container_id }} -mp{{ item.slot }} {{ item.volume }},mp={{ item.path }}"
          loop: "{{ mount_points }}"
          when: mount_points | length > 0

        # =====================================================================
        # Start Container & Wait for IP
        # =====================================================================
        - name: Start container
          ansible.builtin.command:
            cmd: pct start {{ container_id }}
          register: start_result
          failed_when: start_result.rc != 0 and 'already running' not in start_result.stderr

        - name: Wait for container to get IP
          ansible.builtin.command:
            cmd: pct exec {{ container_id }} -- ip -4 addr show eth0
          register: ip_check
          until: ip_check.stdout is search('inet ')
          retries: 15
          delay: 2
          changed_when: false

        - name: Extract and display container IP
          ansible.builtin.set_fact:
            container_ip: "{{ ip_check.stdout | regex_search('inet ([0-9.]+)', '\\1') | first }}"

        - name: Display container status
          ansible.builtin.debug:
            msg: "Container {{ container_id }} configured and ready with IP {{ container_ip }}"
  EOT

  inventory = yamlencode({
    proxmox = {
      hosts = {
        pve = {
          ansible_host = var.proxmox_ssh_host
          ansible_user = "root"
        }
      }
    }
  })
}

# Wait for container to get DHCP IP (Ansible handles the wait internally now)
# Keeping this for backwards compatibility and as a safety margin
resource "time_sleep" "wait_for_ip" {
  depends_on = [
    proxmox_virtual_environment_container.lxc,
    ansible_navigator_run.configure_lxc
  ]
  create_duration = "5s"  # Reduced since Ansible already waits
}

